{
  "name": "@and7ey/opencode-go-usage",
  "version": "2.0.2",
  "description": "OpenCode TUI plugin showing OpenCode Go subscription usage (5h, week, month).",
  "type": "module",
  "license": "MIT",
  "main": "./opencode-go-usage.mjs",
  "exports": {
    ".": "./opencode-go-usage.mjs",
    "./tui": "./opencode-go-usage-tui.mjs",
    "./usage": "./usage.mjs"
  },
  "files": [
    "opencode-go-usage.mjs",
    "opencode-go-usage-tui.mjs",
    "usage.mjs",
    "cli.example.json",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test usage.test.mjs"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.24"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.5.14",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "keywords": [
    "opencode",
    "plugin",
    "tui",
    "usage",
    "quota",
    "opencode-go",
    "subscription"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/and7ey/opencode-go-usage.git"
  },
  "author": "and7ey",
  "bugs": {
    "url": "https://github.com/and7ey/opencode-go-usage/issues"
  },
  "homepage": "https://github.com/and7ey/opencode-go-usage#readme"
}
